    alignPanoSphere(rotation) {
        if (!rotation) return;

        // E57 coordinate map to Three.js: X -> X, Y -> Z, Z -> -Y
        const q = new THREE.Quaternion(rotation[0], rotation[2], -rotation[1], rotation[3]);

        if (this.panoSphere) {
