"    async validateScanRuntime(scan, projectPath) {
        const errors = [];

        const isPointCloudOnly = (!scan.panos || scan.panos.length === 0) && scan.point_cloud_cache;

        // 1. Check panorama count > 0 if not point-cloud-only
        if (!isPointCloudOnly && (!scan.panos || scan.panos.length === 0)) {
            errors.push("No panoramas defined in scan database.");
            return { valid: false, errors };
        }

        if (!isPointCloudOnly) {
            // 2. Check position, rotation, and file existence for each panorama
