"    renderRecentProjects(projects) {
        const container = document.getElementById('recent-projects-list');
        if (!projects || projects.length === 0) {
            container.innerHTML = '<p class="empty-msg">No recent projects found.</p>';
            return;
        }

        container.innerHTML = '';
        projects.forEach(p => {
            const card = document.createElement('div');
            card.className = 'project-card';
            card.innerHTML = `
                <div class="project-card-info">
                    <h4>${p.name}</h4>
                    <p>${p.path}</p>
                </div>
                <button class="btn-delete-project" title="Delete Project">
                    <svg viewBox="0 0 24 24" width="16" height="16" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round">
                        <polyline points="3 6 5 6 21 6"></polyline>
                        <path d="M19 6v14a2 2 0 0 1-2 2H7a2 2 0 0 1-2-2V6m3 0V4a2 2 0 0 1 2-2h4a2 2 0 0 1 2 2v2"></path>
                    </svg>
                </button>
            `;
            card.querySelector('.project-card-info').addEventListener('click', () => this.loadProject(p.path));
            card.querySelector('.btn-delete-project').addEventListener('click', async (e) => {
                e.stopPropagation();
                if (confirm(`Are you sure you want to delete "${p.name}"?\n\nThis will remove it from the dashboard and permanently delete all its database and files on disk.`)) {
                    const res = await window.electronAPI.deleteProject(p.path);
                    if (res.success) {
                        this.loadRecentProjects();
                    } else {
                        alert("Error deleting project: " + res.error);
                    }
                }
            });
            container.appendChild(card);
        });
    }"

