"ipcMain.handle('delete-project', async (event, { path: projectPath }) => {
    try {
        const projectsFile = getProjectsFile();
        let projects = [];
        if (fs.existsSync(projectsFile)) {
            projects = JSON.parse(fs.readFileSync(projectsFile, 'utf-8'));
        }
        projects = projects.filter(p => p.path !== projectPath);
        fs.writeFileSync(projectsFile, JSON.stringify(projects));

        let diskDeleted = true;
        let diskError = null;

        // Clean up project files on disk
        if (fs.existsSync(projectPath)) {
            const pathLower = projectPath.toLowerCase().replace(/\\/g, '/');
            const isSystemDir = pathLower.endsWith('/downloads') || 
                                pathLower.endsWith('/desktop') || 
                                pathLower.endsWith('/documents') ||
                                pathLower.endsWith('/onedrive') ||
                                pathLower === 'c:' || 
                                pathLower === 'c:/';

            if (isSystemDir) {
                diskDeleted = false;
                diskError = "Deletion of system folders (Downloads/Desktop/Documents) is blocked to protect your files.";
            } else {
                try {
                    fs.rmSync(projectPath, { recursive: true, force: true });
                } catch (err) {
                    diskDeleted = false;
                    diskError = err.message;
                }
            }
        }
        return { success: true, diskDeleted, diskError };
    } catch (e) {
        return { success: false, error: e.message };
    }
});"

