+    justify-content: space-between;
+    align-items: center;
+    cursor: pointer;
+    user-select: none;
+    padding-bottom: 12px;
+    border-bottom: 1px solid rgba(255, 255, 255, 0.05);
+    margin-bottom: 18px;
+}
+
+.folder-title-area {
+    display: flex;
+    align-items: center;
+    gap: 12px;
+}
+
+.folder-title {
+    font-size: 1.15rem;
+    font-weight: 600;
+    color: #94a3b8;
+}
+
+.folder-actions {
+    display: flex;
+    align-items: center;
+    gap: 12px;
+}
+
+.btn-delete-folder {
+    background: transparent;
+    border: none;
+    color: #475569;
+    cursor: pointer;
+    padding: 6px;
+    border-radius: 6px;
+    display: flex;
+    align-items: center;
+    justify-content: center;
+    transition: all 0.2s;
+}
+
+.btn-delete-folder:hover {
+    background: rgba(239, 68, 68, 0.1);
+    color: #ef4444;
+}
+
+.folder-toggle-icon {
+    transition: transform 0.2s;
+    color: #64748b;
+    display: flex;
+    align-items: center;
+}
+
+.folder-section.collapsed .folder-toggle-icon {
+    transform: rotate(-90deg);
+}
+
+.folder-projects {
+    display: grid;
+    grid-template-columns: repeat(auto-fill, minmax(280px, 1fr));
+    gap: 20px;
+}
+
+.folder-section.collapsed .folder-projects {
+    display: none;
+}

