"    findGroundHeight(pos, pointCloud, defaultOffset = 1.6) {
        if (!pointCloud || !pointCloud.geometry) return pos.y - defaultOffset;

        const positions = pointCloud.geometry.attributes.position.array;
        const count = positions.length / 3;

        const R = 0.5;
        const R_sq = R * R;

        let yValues = [];
        const stride = Math.max(1, Math.floor(count / 50000));

        for (let i = 0; i < count; i += stride) {
            const px = positions[i * 3];
            const py = positions[i * 3 + 1];
            const pz = positions[i * 3 + 2];

            // Translate to world coordinates based on active pointCloud alignment translation
            const worldX = px + pointCloud.position.x;
            const worldY = py + pointCloud.position.y;
            const worldZ = pz + pointCloud.position.z;

            const dx = worldX - pos.x;
            const dz = worldZ - pos.z;
            const distSq = dx * dx + dz * dz;

            if (distSq < R_sq && worldY < pos.y) {
                yValues.push(worldY);
            }
        }

        if (yValues.length === 0) {
            return pos.y - defaultOffset;
        }

        yValues.sort((a, b) => a - b);

        // Filter out tripod points/scanner housing by selecting points at least 1.0m below camera
        const floorCandidates = yValues.filter(y => y < pos.y - 1.0);
        if (floorCandidates.length > 0) {
            // Take the 90th percentile of points below the camera to represent floor surface level
            const idx = Math.floor(floorCandidates.length * 0.9);
            return floorCandidates[idx];
        }

        const idx = Math.floor(yValues.length * 0.9);
        return yValues[idx];
    }

