2:     /**
3:      * Evaluates spatial proximity in the target scan pool to find the nearest match.
4:      * Standardized signature permits future swap-ins of spatial indexes (e.g. KD-Tree)
5:      * without modifications to the caller logic.
6:      * 
7:      * @param {Object} referencePano - Pano from the previous scan date
8:      * @param {Object[]} targetScanPanos - Panos in the target scan date
9:      * @param {number} maxDistance - Spatial distance threshold (read from project settings)
10:      * @returns {Object|null} Nearest target panorama, or null if threshold exceeded (abort transit)
11:      */
12:     static findNearestPano(referencePano, targetScanPanos, maxDistance = 10.0) {
13:         if (!referencePano || !targetScanPanos || targetScanPanos.length === 0) {
14:             return null;
15:         }
16: 
17:         const refPos = referencePano.position; // Python space: [x, y, z]
18:         const refFloor = referencePano.floor_id;
19: 
20:         // Rule 1: Prioritize matching the active floor first
21:         const sameFloorPanos = targetScanPanos.filter(p => p.floor_id === refFloor);
22:         const searchPool = sameFloorPanos.length > 0 ? sameFloorPanos : targetScanPanos;
23: 
24:         let closestPano = null;
25:         let minDist = Infinity;
26: 
27:         // Abstracted search pool loops. Swappable with spatial indexes.
28:         searchPool.forEach(pano => {
29:             const dx = pano.position[0] - refPos[0];
30:             const dy = pano.position[1] - refPos[1];
31:             const dz = pano.position[2] - refPos[2];
32:             const dist = Math.sqrt(dx * dx + dy * dy + dz * dz);
33:             
34:             if (dist < minDist) {
35:                 minDist = dist;
36:                 closestPano = pano;
37:             }
38:         });
39: 
40:         // Explicit fallback limit check to prevent jumping into unrelated scan sectors
41:         if (minDist > maxDistance) {
42:             console.warn(`AutoStack target nearest node is ${minDist.toFixed(2)}m away (limit: ${maxDistance}m). Aborting.`);
43:             return null;
44:         }
45: 
46:         return closestPano;
47:     }
